    .endr

    .section .text.secure_reset, "ax"
    .global secure_reset
    .thumb_func
secure_reset:
    LDR     r0, =__data_load_start__
    LDR     r1, =__data_start__
    LDR     r2, =__data_end__
1:  CMP     r1, r2
    BHS     2f
    LDR     r3, [r0], #4
    STR     r3, [r1], #4
    B       1b
2:
    LDR     r1, =__bss_start__
    LDR     r2, =__bss_end__
    MOVS    r3, #0
1:  CMP     r1, r2
    BHS     2f
    STR     r3, [r1], #4
    B       1b
2:
    @ Grant FPU access in both security states.
    LDR     r0, =0xE000ED88                 @ CPACR
    LDR     r1, =0x00F00000
    STR     r1, [r0]
    MOVW    r1, #0x0C00
    STR     r1, [r0, #4]                   @ NSACR

    @ Attribute the gateway, manager code and manager data on AN547.
    LDR     r0, =0xE000EDD0                 @ SAU_CTRL
    MOVS    r1, #0
    STR     r1, [r0, #8]                   @ SAU_RNR
    LDR     r1, =__gateway_start__
    STR     r1, [r0, #12]                  @ SAU_RBAR
    LDR     r1, =__gateway_limit__
    ORR     r1, r1, #3                     @ NSC, ENABLE
    STR     r1, [r0, #16]                  @ SAU_RLAR
    MOVS    r1, #1
    STR     r1, [r0, #8]
    LDR     r1, =__manager_code_start__
    STR     r1, [r0, #12]
    LDR     r1, =__manager_code_limit__
    ORR     r1, r1, #1                     @ ENABLE
    STR     r1, [r0, #16]
    MOVS    r1, #2
    STR     r1, [r0, #8]
    LDR     r1, =__manager_ram_start__
    STR     r1, [r0, #12]
    LDR     r1, =__manager_ram_limit__
    ORR     r1, r1, #1                     @ ENABLE
    STR     r1, [r0, #16]
    MOVS    r1, #1
    STR     r1, [r0]
    DSB
    ISB

    @ Start the Non-secure manager from its reset vector.
    LDR     r0, =__manager_code_start__
    LDR     r1, =0xE002ED08                 @ VTOR_NS
    STR     r0, [r1]
    LDR     r1, [r0]
    MSR     MSP_NS, r1
    LDR     r0, [r0, #4]
    BIC     r0, r0, #1
    BXNS    r0

    @ Report any unexpected Secure exception to the QEMU runner.
    .thumb_func
secure_fault:
    MOVS    r0, #4
    LDR     r1, =secure_fault_message
    BKPT    #0xAB
    MOVS    r0, #0x18
    LDR     r1, =0x20023
    BKPT    #0xAB
    B       .

    .section .rodata.secure_fault, "a"
secure_fault_message:
